    50	fn load_from_file(
    51	  path: &Path,
    52	  settings: &Settings,
    53	) -> RunResult<'static, Option<BTreeMap<String, String>>> {
    54	  if path.is_dir() {
    55	    return Ok(None);
    56	  }
    57	
    58	  let file = match File::open(path) {
    59	    Ok(file) => file,
    60	    Err(source) => {
    61	      if source.kind() == io::ErrorKind::NotFound {
    62	        return Ok(None);
    63	      }
    64	      return Err(Error::FilesystemIo {
    65	        path: path.into(),
    66	        source,
    67	      });
    68	    }
    69	  };
    70	
    71	  let mut dotenv = BTreeMap::new();
    72	
    73	  for result in dotenvy::from_read_iter(file) {
    74	    let (key, value) = result.map_err(|dotenv_error| Error::Dotenv {
    75	      dotenv_error,
    76	      path: path.into(),
    77	    })?;
    78	
    79	    if settings.dotenv_override || env::var_os(&key).is_none() {
    80	      dotenv.insert(key, value);
    81	    }
    82	  }
    83	
    84	  Ok(Some(dotenv))
    85	}
