   323	                    if matches!(c, '!' | '"' | '$' | '\\' | '`') {
   324	                      print!("\\");
   325	                    }
   326	                    print!("{c}");
   327	                  }
   328	                  println!("\"");
   329	                }
   330	              }
   331	            }
   332	          }
   333	        }
   334	
   335	        Ok(())
   336	      }
   337	      _ => unreachable!(),
   338	    }
   339	  }
